"""Current artifacts bind exact generated bytes and their calculation dependencies."""

import json
import sys
from pathlib import Path
from typing import TYPE_CHECKING, cast

import pytest

from quality import artifacts
from quality.assurance import input_fingerprint

if TYPE_CHECKING:
    from collections.abc import Callable

# The published seal helper declares a bare dict; restate the asserted shape.
seal = cast("Callable[..., dict[str, object]]", artifacts.seal)


def release(root: Path) -> Path:
    (root / "src").mkdir()
    _ = (root / "src/model.py").write_text("x=1")
    target = root / "outputs/current"
    target.mkdir(parents=True)
    _ = (target / "table.csv").write_text("value\n1\n")
    return target


def test_valid_artifacts_and_nonrecursive_manifest(tmp_path: Path) -> None:
    m = artifacts
    target = release(tmp_path)
    _ = seal(tmp_path, target)
    assert m.verify(tmp_path, target) == []
    first = (target / "release_manifest.json").read_bytes()
    _ = seal(tmp_path, target)
    assert first == (target / "release_manifest.json").read_bytes()


@pytest.mark.parametrize("change", ["table", "source", "missing", "extra"])
def test_stale_or_changed_release_rejected(tmp_path: Path, change: str) -> None:
    m = artifacts
    target = release(tmp_path)
    _ = seal(tmp_path, target)
    if change == "table":
        _ = (target / "table.csv").write_text("value\n2\n")
    elif change == "source":
        _ = (tmp_path / "src/model.py").write_text("x=2")
    elif change == "missing":
        (target / "table.csv").unlink()
    else:
        _ = (target / "untracked.txt").write_text("unexpected")
    assert m.verify(tmp_path, target)


def test_unsafe_manifest_path_rejected(tmp_path: Path) -> None:
    m = artifacts
    target = release(tmp_path)
    _ = seal(tmp_path, target)
    p = target / "release_manifest.json"
    d = cast("dict[str, object]", json.loads(p.read_text()))
    d["artifacts"] = {"../../escape": "0" * 64}
    _ = p.write_text(json.dumps(d))
    assert m.verify(tmp_path, target)


def test_generated_outputs_have_separate_fingerprint(tmp_path: Path) -> None:
    m = artifacts
    target = release(tmp_path)
    a = m.artifact_dependency_fingerprint(tmp_path)
    _ = (target / "table.csv").write_text("value\n2\n")
    assert a != m.artifact_dependency_fingerprint(tmp_path)


def test_current_configuration_is_assurance_input(tmp_path: Path) -> None:
    (tmp_path / "config").mkdir()
    f = tmp_path / "config/reference.json"
    _ = f.write_text("{}")
    before = input_fingerprint(tmp_path)
    _ = f.write_text('{"changed":true}')
    assert before != input_fingerprint(tmp_path)


def test_empty_unsafe_and_missing_releases(tmp_path: Path) -> None:
    m = artifacts
    target = tmp_path / "outputs/current"
    target.mkdir(parents=True)
    with pytest.raises(ValueError, match="Cannot seal an empty artifact set"):
        _ = seal(tmp_path, target)
    with pytest.raises(ValueError, match="Release output must be inside repository outputs"):
        _ = seal(tmp_path, tmp_path / "elsewhere")
    assert m.verify(tmp_path, target)
    assert m.verify(tmp_path, tmp_path / "elsewhere")


@pytest.mark.parametrize("value", [[], {"schema_version": 2}, {"schema_version": 1, "artifacts": {}}, None])
def test_malformed_manifest_fails(tmp_path: Path, value: object) -> None:
    m = artifacts
    target = release(tmp_path)
    _ = (target / "release_manifest.json").write_text(json.dumps(value))
    assert m.verify(tmp_path, target)


def test_symlinks_are_not_release_artifacts(tmp_path: Path) -> None:
    target = release(tmp_path)
    (target / "link").symlink_to(target / "table.csv")
    with pytest.raises(ValueError, match="Manifest path escapes its root or is a symlink"):
        _ = seal(tmp_path, target)


def test_cli_seal_and_verify(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    m = artifacts
    target = release(tmp_path)
    monkeypatch.setattr(m, "__file__", str(tmp_path / "quality/artifacts.py"))
    monkeypatch.setattr(sys, "argv", ["artifacts", "seal", "--output", "outputs/current"])
    assert m.main() == 0
    monkeypatch.setattr(sys, "argv", ["artifacts", "verify", "--output", "outputs/current"])
    assert m.main() == 0
    _ = (target / "table.csv").write_text("changed")
    assert m.main() == 1
